import React, { useCallback, useMemo } from 'react';
import { useIntl } from 'react-intl';

import {
  BasicContainer,
  BrandAvatarList,
  BreadcrumbChips,
  ComparisonLine,
  DataStateHandler,
  SubFilter,
  Waterfall,
} from 'components';
import { usePageFilterManagement } from 'hooks';

import { overviewCardIdToPresetKpiValue } from '../../../../utils/kpiPreset';
import {
  getPerformanceAndBreakdownViewByLabel,
  handlePerformanceAndBreakdownWaterfallBarClick,
} from '../../config/performanceAndBreakdownDeepDive';
import {
  INNOVATION_HUB_PAGE_NAME,
  PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_TITLE_I18N_ID,
  PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PLUGIN_COLORS,
  PERFORMANCE_AND_BREAKDOWN_WATERFALL_COLORS,
  PERFORMANCE_AND_BREAKDOWN_WATERFALL_OPTIONS_DATA_API_KEY,
  PERFORMANCE_AND_BREAKDOWN_WATERFALL_OPTIONS_STATE_KEY,
} from '../../constants';
import {
  usePerformanceAndBreakdownDeepDiveData,
  usePerformanceAndBreakdownFilters,
  usePerformanceAndBreakdownSectionUi,
  usePerformanceAndBreakdownViewBySync,
} from '../../hooks';
import type {
  PerformanceAndBreakdownInnovationStageFilter,
  PerformanceAndBreakdownWaterfallContextKey,
} from '../../types';
import {
  StyledBodyContainer,
  StyledComparisonLineContainer,
  StyledLegendContainer,
  StyledWaterfallChartContainer,
} from './DeepDiveSection.styles';

const SKELETON_PROPS = {
  height: '360px',
  width: '100%',
  length: 1,
  borderRadius: 'none' as const,
};

const DEEP_DIVE_WATERFALL_OPTIONS = {
  animation: false as const,
  datasets: {
    bar: {
      categoryPercentage: 0.85,
      barPercentage: 0.92,
    },
  },
  plugins: {
    connectBars: {
      display: true,
      color:
        PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PLUGIN_COLORS.connectBars,
    },
    verticalGuidelines: {
      display: true,
      displayLeftY: false,
      displayRightY: false,
      displayAxisX: true,
      color:
        PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PLUGIN_COLORS.verticalGuidelines,
    },
  },
};

interface DeepDiveSectionProps {
  contextKey: PerformanceAndBreakdownWaterfallContextKey;
  kpi: string | undefined;
  innovationStageFilter: PerformanceAndBreakdownInnovationStageFilter | null;
  onClearInnovationStage: () => void;
  dataTestId?: string;
}

export const DeepDiveSection: React.FC<DeepDiveSectionProps> = ({
  contextKey,
  kpi,
  innovationStageFilter,
  onClearInnovationStage,
  dataTestId,
}) => {
  const { formatMessage } = useIntl();
  const { view, data } = usePerformanceAndBreakdownDeepDiveData(
    contextKey,
    innovationStageFilter,
  );
  const { applied, dataFilters } = usePerformanceAndBreakdownFilters();
  const { updateForm, apply } = usePageFilterManagement(
    INNOVATION_HUB_PAGE_NAME,
  );
  const { activeViewBy, isViewByDisabled } =
    usePerformanceAndBreakdownViewBySync(contextKey);
  const { measure, stateMessage } = usePerformanceAndBreakdownSectionUi(
    kpi,
    view,
  );

  const disabledIndexes = useMemo(() => {
    if (!data) return [];
    return data.disabledIndexes ?? [0, data.labels.length - 1];
  }, [data]);

  const isBarInteractionEnabled = activeViewBy !== 'sku';

  const handleBarClick = useCallback(
    (index: number | null) => {
      if (index === null || !data || !isBarInteractionEnabled) {
        return;
      }

      handlePerformanceAndBreakdownWaterfallBarClick({
        index,
        filterValues: data.filterValues,
        viewBy: activeViewBy,
        applied,
        dataFilters,
        updateForm,
        apply,
        disabledIndexes,
      });
    },
    [
      data,
      activeViewBy,
      applied,
      dataFilters,
      updateForm,
      apply,
      disabledIndexes,
      isBarInteractionEnabled,
    ],
  );

  const renderLegend = useCallback(() => {
    const brandsData = data?.images?.data?.map((brand) => {
      const { mainBrand, badgeFlag, title, description } = brand;

      return {
        title,
        ...(description ? { description } : {}),
        ...(mainBrand?.src ? { mainBrand } : {}),
        ...(badgeFlag?.src ? { badgeFlag } : {}),
      };
    });

    if (!brandsData?.length) {
      return null;
    }

    return (
      <StyledLegendContainer>
        <BrandAvatarList
          data={brandsData}
          length={data?.labels.length}
          borderConfig={{ marginLeft: 16, marginRight: 16 }}
          gridConfig={{ paddingLeft: 0, paddingRight: 0 }}
          dataTestId={dataTestId ? `${dataTestId}-legend` : undefined}
        />
      </StyledLegendContainer>
    );
  }, [data, dataTestId]);

  const kpiSlug = useMemo(() => {
    if (!kpi || kpi === 'undefined') return 'volume';
    return overviewCardIdToPresetKpiValue(kpi).replaceAll('_', '-');
  }, [kpi]);

  const rightContent = useMemo(
    () => (
      <SubFilter.Select
        apiKey={`innovation-hub-waterfall-options_${kpiSlug}`}
        dataApiKey={PERFORMANCE_AND_BREAKDOWN_WATERFALL_OPTIONS_DATA_API_KEY}
        params={{}}
        stateKey={PERFORMANCE_AND_BREAKDOWN_WATERFALL_OPTIONS_STATE_KEY}
        contextKey={contextKey}
        valueLabel="View by:"
        shape="pill"
        size="medium"
        chips
        clearChips={false}
        disabled={isViewByDisabled}
      />
    ),
    [kpiSlug, contextKey, isViewByDisabled],
  );

  const breadcrumb = useMemo(() => {
    if (!innovationStageFilter) {
      return undefined;
    }

    return (
      <BreadcrumbChips
        rootLabel={innovationStageFilter.label}
        path={[getPerformanceAndBreakdownViewByLabel(activeViewBy)]}
        onGoToStep={() => onClearInnovationStage()}
        dataTestId={dataTestId ? `${dataTestId}-breadcrumb` : undefined}
      />
    );
  }, [activeViewBy, dataTestId, innovationStageFilter, onClearInnovationStage]);

  return (
    <BasicContainer
      header={{
        title: formatMessage({
          id: PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_TITLE_I18N_ID,
        }),
        measure,
        titleSize: 'H4',
        rightContent,
        bottomTag: breadcrumb,
      }}
      layout={{
        border: 'small',
        borderRadius: 'large',
        shadow: 'small',
        bodyPadding: false,
        bottomSeparator: 'border',
      }}
      fullWidth
      dataTestId={dataTestId}
    >
      <DataStateHandler
        loading={view === 'loading'}
        error={view === 'error'}
        empty={view === 'empty' || !data}
        dataTestId={dataTestId ? `${dataTestId}-state` : undefined}
        message={stateMessage}
        skeletonProps={SKELETON_PROPS}
      >
        {view === 'ready' && data ? (
          <StyledBodyContainer>
            <StyledWaterfallChartContainer>
              <Waterfall
                key={activeViewBy}
                values={data.values}
                labels={data.labels}
                formattedData={data.formattedData}
                specialIndexes={data.specialIndexes}
                colors={PERFORMANCE_AND_BREAKDOWN_WATERFALL_COLORS}
                showLabels={false}
                options={DEEP_DIVE_WATERFALL_OPTIONS}
                interactiveConfig={{
                  onBarSelect: handleBarClick,
                  clickability: {
                    enabled: isBarInteractionEnabled,
                    disabledIndexes,
                  },
                  renderLegend,
                  fillHeight: true,
                  showTooltip: true,
                }}
              />
            </StyledWaterfallChartContainer>
            {data.comparisonLine?.data && (
              <StyledComparisonLineContainer>
                <ComparisonLine
                  key={activeViewBy}
                  data={data.comparisonLine.data}
                  gridColumnsLength={data.labels.length}
                  borderConfig={{ marginLeft: 16, marginRight: 16 }}
                  gridConfig={{ paddingLeft: 0, paddingRight: 0 }}
                />
              </StyledComparisonLineContainer>
            )}
          </StyledBodyContainer>
        ) : null}
      </DataStateHandler>
    </BasicContainer>
  );
};
